-- ============================================================================
-- godbsync CI 种子数据：Oracle 源端
--
-- 版本要求：IDENTITY 列需 Oracle 12c+（CI 用 23c FREE）。若要在 11g XE 上跑，
-- 需把 T_ANCHOR.ID 改成 sequence + trigger，其余语句不用动。
--
-- 与 mysql.sql / postgresql.sql / sqlserver.sql 保持一致：同名、同列序、同语义类型。
-- 注意事项：
--   * 表名/列名不加引号 → Oracle 存为大写，与另外三个方言的全大写命名一致。
--     这一点是硬要求：oracle.Writer.GenerateCreate 用 "..." 双引号原样建表，
--     而 TableExists 查 all_tables 时会 ToUpper；小写表名会让「表已存在」判定失效。
--   * 保留字列名（ORDER/GROUP/DESC/KEY）必须加双引号，且引号内保持大写。
--   * CLOB 字面量受 VARCHAR2 4000 字节上限约束，长文本用 RPAD + 拼接绕过。
--   * emoji 依赖数据库字符集 AL32UTF8；执行时 NLS_LANG 需为 *.AL32UTF8。
-- ============================================================================

WHENEVER SQLERROR EXIT SQL.SQLCODE
SET DEFINE OFF
SET ECHO OFF
SET PAGESIZE 100

-- 幂等清理：只删本脚本创建的表，避免影响同 schema 下的其他对象。
BEGIN
  FOR t IN (SELECT table_name FROM user_tables
            WHERE table_name IN ('T_ANCHOR','T_TYPES','T_RESERVED','T_NOPK','T_EMPTY')) LOOP
    EXECUTE IMMEDIATE 'DROP TABLE "' || t.table_name || '" CASCADE CONSTRAINTS';
  END LOOP;
END;
/

-- ---------------------------------------------------------------------------
-- T_ANCHOR：1200 行，单列主键（IDENTITY）+ 单调时间列
-- ---------------------------------------------------------------------------
CREATE TABLE T_ANCHOR (
  ID NUMBER(19) GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) PRIMARY KEY,
  NAME VARCHAR2(64) NOT NULL,
  AMOUNT NUMBER(18,4),
  UPDATED_AT TIMESTAMP(6) NOT NULL
);

COMMENT ON TABLE T_ANCHOR IS '断点续传与水位探针';
COMMENT ON COLUMN T_ANCHOR.NAME IS '业务名称（含中文，验证字符集透传）';
COMMENT ON COLUMN T_ANCHOR.UPDATED_AT IS '增量水位列，按行号单调递增';

INSERT INTO T_ANCHOR (NAME, AMOUNT, UPDATED_AT)
SELECT 'row-' || LPAD(LEVEL, 5, '0') || '-中文',
       ROUND(LEVEL * 1.2345, 4),
       TIMESTAMP '2024-01-01 00:00:00' + NUMTODSINTERVAL(LEVEL, 'SECOND')
FROM DUAL CONNECT BY LEVEL <= 1200;

-- ---------------------------------------------------------------------------
-- T_TYPES：类型边界探针（含 CLOB 长文本，故用 PL/SQL 块插入）
-- ---------------------------------------------------------------------------
CREATE TABLE T_TYPES (
  ID NUMBER(10) NOT NULL PRIMARY KEY,
  C_DEC NUMBER(38,10),
  C_BIG NUMBER(19),
  C_FLOAT BINARY_DOUBLE,
  C_VC VARCHAR2(255),
  C_TXT CLOB,
  C_DATE DATE,
  C_TS TIMESTAMP(6),
  C_BOOL NUMBER(1),
  C_BIN BLOB
);

COMMENT ON TABLE T_TYPES IS '类型映射边界探针';

DECLARE
  v_txt CLOB;
BEGIN
  -- 1300 字符 ≈ 3900 字节（低于 VARCHAR2 的 4000 字节上限），再拼三次得到 3900 字符的 CLOB。
  v_txt := RPAD('长文本测试', 1300, '文');
  v_txt := v_txt || v_txt || v_txt;

  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (1, 1234567890123456789012345678.0123456789, 9223372036854775807, 3.141592653589793d,
          '普通中文与 ASCII 混排 abcXYZ', v_txt,
          DATE '2024-03-05', TIMESTAMP '2024-03-05 12:34:56.123456', 1,
          HEXTORAW('000102030405060708090A0B0C0D0E0F'));

  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (2, -1234567890123456789012345678.0123456789, -9223372036854775808, -2.718281828459045d,
          '负数与极小值', TO_CLOB('短文本'),
          DATE '1970-01-02', TIMESTAMP '1970-01-02 00:00:00.000001', 0,
          HEXTORAW('FFEEDDCCBBAA99887766554433221100'));

  -- 空串：Oracle 语义下 '' 即 NULL，这是与另外三个方言最大的行为差异（故意保留）。
  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (3, 0.0000000001, 0, 0d, '', EMPTY_CLOB(),
          DATE '2024-12-31', TIMESTAMP '2024-12-31 23:59:59.999999', 0,
          HEXTORAW('00'));

  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (4, 9999999999999999999999999999.9999999999, 1, 1.5d,
          '特殊字符: 单引号 '' 反斜杠 \ 制表 ' || CHR(9) || ' 换行 ' || CHR(10) || ' 表情 😀🎉 结束',
          TO_CLOB('含 emoji 的文本 😀'),
          DATE '2000-02-29', TIMESTAMP '2000-02-29 00:00:00.000000', 1,
          HEXTORAW('DEADBEEF'));

  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (5, -0.0000000001, -1, -1.5d,
          '边界长度: 这是一个用于验证 255 字符上限的填充值', TO_CLOB(RPAD('x', 100, 'x')),
          DATE '2038-01-18', TIMESTAMP '2038-01-19 03:14:07.000000', 1, NULL);

  INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN)
  VALUES (6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
END;
/

-- ---------------------------------------------------------------------------
-- T_RESERVED：保留字列名（引号内必须大写，与 Oracle 的默认折叠规则一致）
-- ---------------------------------------------------------------------------
CREATE TABLE T_RESERVED (
  ID NUMBER(10) NOT NULL PRIMARY KEY,
  "ORDER" NUMBER(10),
  "GROUP" VARCHAR2(32),
  "DESC" VARCHAR2(64),
  "KEY" VARCHAR2(32)
);

COMMENT ON TABLE T_RESERVED IS '保留字列名探针';

INSERT INTO T_RESERVED (ID, "ORDER", "GROUP", "DESC", "KEY") VALUES (1, 100, 'g-alpha', '第一行描述', 'k1');
INSERT INTO T_RESERVED (ID, "ORDER", "GROUP", "DESC", "KEY") VALUES (2, -100, 'g-beta', '第二行描述', 'k2');
INSERT INTO T_RESERVED (ID, "ORDER", "GROUP", "DESC", "KEY") VALUES (3, 0, '', '第三行描述', 'k3');

-- ---------------------------------------------------------------------------
-- T_NOPK：无主键表。Oracle 源会走 ROWID 断点续传（与另外三个方言的无序全量不同）。
-- ---------------------------------------------------------------------------
CREATE TABLE T_NOPK (
  K1 NUMBER(10),
  K2 VARCHAR2(32),
  K3 NUMBER(10,2)
);

COMMENT ON TABLE T_NOPK IS '无主键表';

INSERT INTO T_NOPK (K1, K2, K3)
SELECT LEVEL, 'np-' || LEVEL, ROUND(LEVEL * 1.25, 2)
FROM DUAL CONNECT BY LEVEL <= 50;

-- ---------------------------------------------------------------------------
-- T_EMPTY：0 行表
-- ---------------------------------------------------------------------------
CREATE TABLE T_EMPTY (
  ID NUMBER(10) NOT NULL PRIMARY KEY,
  V VARCHAR2(10)
);

COMMENT ON TABLE T_EMPTY IS '空表';

COMMIT;

-- ---------------------------------------------------------------------------
-- 自检：各表预期行数
-- ---------------------------------------------------------------------------
SELECT 'T_ANCHOR' AS TAB_, COUNT(*) AS ROWS_ FROM T_ANCHOR
UNION ALL SELECT 'T_TYPES', COUNT(*) FROM T_TYPES
UNION ALL SELECT 'T_RESERVED', COUNT(*) FROM T_RESERVED
UNION ALL SELECT 'T_NOPK', COUNT(*) FROM T_NOPK
UNION ALL SELECT 'T_EMPTY', COUNT(*) FROM T_EMPTY;

EXIT;
